template <typename scalar_t>
__global__ __launch_bounds__(512)
void rmsnorm_kernel(
    const scalar_t* __restrict__ input,
    const scalar_t* __restrict__ weight,
    scalar_t* __restrict__ output,
    int hidden_size,
    float eps
) {
    int row = blockIdx.x;
    const scalar_t* x = input + row * hidden_size;
    scalar_t* o = output + row * hidden_size;

    constexpr int VEC_SIZE = sizeof(float4) / sizeof(scalar_t);
    const float4* x_vec = reinterpret_cast<const float4*>(x);
    const float4* w_vec = reinterpret_cast<const float4*>(weight);
    float4* o_vec = reinterpret_cast<float4*>(o);
    int num_vecs = hidden_size / VEC_SIZE;

    float sum_sq = 0.0f;
    for (int i = threadIdx.x; i < num_vecs; i += blockDim.x) {
        float4 xv = x_vec[i];
        const scalar_t* v = reinterpret_cast<const scalar_t*>(&xv);
        #pragma unroll
        for (int j = 0; j < VEC_SIZE; j++) {
            float val = static_cast<float>(v[j]);
            sum_sq += val * val;
        }
    }
    for (int i = num_vecs * VEC_SIZE + threadIdx.x; i < hidden_size; i += blockDim.x) {
        float val = static_cast<float>(__ldg(&x[i]));
        sum_sq += val * val;
    }

    for (int offset = warpSize / 2; offset > 0; offset >>= 1)
        sum_sq += __shfl_down_sync(0xffffffff, sum_sq, offset);

    __shared__ float shared[16];
    int lane = threadIdx.x & 31;
    int warp_id = threadIdx.x >> 5;

    if (lane == 0) shared[warp_id] = sum_sq;
    __syncthreads();

    if (warp_id == 0) {
        int num_warps = (blockDim.x + 31) >> 5;
        sum_sq = (lane < num_warps) ? shared[lane] : 0.0f;
        for (int offset = warpSize / 2; offset > 0; offset >>= 1)
            sum_sq += __shfl_down_sync(0xffffffff, sum_sq, offset);
    }

    __shared__ float s_rms_inv;
    if (threadIdx.x == 0) {
        s_rms_inv = rsqrtf(sum_sq / hidden_size + eps);
    }
    __syncthreads();

    float rms_inv = s_rms_inv;

    for (int i = threadIdx.x; i < num_vecs; i += blockDim.x) {
        float4 xv = x_vec[i];
        float4 wv = w_vec[i];
        float4 ov;
        const scalar_t* xv_ptr = reinterpret_cast<const scalar_t*>(&xv);
        const scalar_t* wv_ptr = reinterpret_cast<const scalar_t*>(&wv);
        scalar_t* ov_ptr = reinterpret_cast<scalar_t*>(&ov);
        #pragma unroll
        for (int j = 0; j < VEC_SIZE; j++) {
            ov_ptr[j] = static_cast<scalar_t>(static_cast<float>(xv_ptr[j]) * rms_inv * static_cast<float>(wv_ptr[j]));
        }
        o_vec[i] = ov;
    }
    for (int i = num_vecs * VEC_SIZE + threadIdx.x; i < hidden_size; i += blockDim.x) {
        float val = static_cast<float>(__ldg(&x[i]));
        float w = static_cast<float>(__ldg(&weight[i]));
        o[i] = static_cast<scalar_t>(val * rms_inv * w);
    }
}

